  "title": title,
  "url": url,
  "style": {
    "layout_flexGrow": 1,
    "layout_flexBasisPercent": size
  }
});

var sk = java.ajax("https://m.xmitxt.com/shuku/");

var fl = java.ajax("https://m.xmitxt.com/type.html");

var ph =
java.ajax("https://m.xmitxt.com/rank.html");

var wb =java.ajax("https://m.xmitxt.com/full/");

