a = org.jsoup.Jsoup.parse(sk).select(".library a")

b = org.jsoup.Jsoup.parse(fl).select(".sort a")

c = org.jsoup.Jsoup.parse(ph).select(".top a");

d =org.jsoup.Jsoup.parse(wb).select(".sort a");

push("🔥全部小说🔥",null,1)
    for(var i=0;i<a.length;i++){
        title=a[i].text()
        url=a[i].attr("href")
        size=0.33;
        title = String(title).replace(/\s/g, "");    
        url=baseUrl+String(url).replace(/\d+\.html$/,"")+"{{page}}.html";
        push(title,url,size)
    };

push("🔥分类小说🔥",null,1)
let count=0;
   for(var i=0;i<b.length;i++){
        title=b[i].text()
        url=b[i].attr("href")
        size=0.33;
        title = String(title).replace(/\s/g, "");
        if (title === "全部分类") {
        count++; 
        if (count === 1) {
        continue;
          }
        }       
        url=baseUrl+String(url).replace(/\d+\.html$/,"")+"{{page}}.html";
        push(title,url,size)
    };

push("🔥排行榜单🔥",null,1)
    for(var i=0;i<c.length;i++){
        title=c[i].text()
        url=c[i].attr("href")
        size=0.33;
        title = String(title).replace(/\s/g, "");
        url=baseUrl+String(url).replace(/\d+\.html$/,"")+"{{page}}.html";
        push(title,url,size)
    };

push("🔥完本小说🔥",null,1)
    for(var i=0;i<d.length;i++){
        title=d[i].text()
        url=d[i].attr("href")
        size=0.33;
        title = String(title).replace(/\s/g, "");
        url=baseUrl+String(url).replace(/\d+\.html$/,"")+"{{page}}.html";
        push(title,url,size)
    };

} else {

  java.toast("🤔列表刷新失败！！！");
}
JSON.stringify(result);

