source.exploreUrl:
@js:
sort=[];
push=(title,url,type1,type2)=>
	sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});

//push("最近更新","/last",1,1);

push('🔥推荐🔥', null, 1, 1);
[["男生","male"],["女生","female"]].map([title,uri]=>push(title, `/blist/${uri}`, 1, 0.4));


bd=[["新书","newhot"],["人气","monthvisit"],["推荐","allvote"]];
[["连载","0_2"],["完结","0_1"]].map([title,id]=>{
	push('🔥总榜·'+title+'🔥', null, 1, 1);
		bd.map([title,uri]=>{			
		  	url= `/blist/${uri}_${id}_{{page}}.htm`; 
				push(title, url, 1, 0.25);			

			});
	});

dj=["全部小说","玄幻魔法","修真武侠","言情小说","历史军事","游戏竞技","科幻空间","悬疑惊悚","同人小说","都市小说","官场职场","穿越时空","青春校园","其他小说"];
		push('🔥点击榜🔥', null, 1, 1);
		dj.map((title,index)=>{
				index++;
				url= `/blist/class/{{(${index}-1)}}<,/{{page}}>.htm`;				
    push(title, url, 1, 0.25);
			});

fl=["全部小说","玄幻魔法","修真武侠","言情小说","历史军事","游戏竞技","科幻空间","悬疑惊悚","同人小说","都市小说","官场职场","穿越时空","青春校园","其他小说"];
[["全部","0"],["连载","2"],["完结","1"]].map([title,id]=>{
		push('🔥人气·'+title+'🔥', null, 1, 1);
		fl.map((title,index)=>{
				index++;
				url= `/blist/monthvisit_{{(${index}-1)}}_${id}_{{page}}.htm`;				
    push(title, url, 1, 0.25);
    });
		});

wj=["全部小说","玄幻魔法","修真武侠","言情小说","历史军事","游戏竞技","科幻空间","悬疑惊悚","同人小说","都市小说","官场职场","穿越时空","青春校园","其他小说"];
		push('🔥完结榜🔥', null, 1, 1);
		wj.map((title,index)=>{
				index++;
				url= `/blist/full/{{(${index}-1)}}<,/{{page}}>.htm`;				
    push(title, url, 1, 0.25);
